53	void appendAcceptedTokens(DecodingInferenceContext& context, Tensor& hostAcceptLengths, Tensor& hostAcceptedTokenIds,
54	    Tensor const& deviceAcceptLength, Tensor const& deviceAcceptedTokenIds, int32_t maxAcceptDepth,
55	    tokenizer::Tokenizer const& tokenizer, cudaStream_t stream)
56	{
57	    int32_t const activeBatchSize = context.activeBatchSize;
58	
59	    check::check(hostAcceptLengths.reshape({activeBatchSize}), "Tensor reshape failed");
60	    check::check(hostAcceptedTokenIds.reshape({activeBatchSize, maxAcceptDepth}), "Tensor reshape failed");
61	    int32_t* hostAcceptLengthsData = hostAcceptLengths.dataPointer<int32_t>();
62	    int32_t* hostAcceptedTokenIdsData = hostAcceptedTokenIds.dataPointer<int32_t>();
63	
64	    CUDA_CHECK(cudaMemcpyAsync(hostAcceptLengthsData, deviceAcceptLength.rawPointer(),
65	        activeBatchSize * sizeof(int32_t), cudaMemcpyDeviceToHost, stream));
66	    CUDA_CHECK(cudaMemcpyAsync(hostAcceptedTokenIdsData, deviceAcceptedTokenIds.rawPointer(),
67	        activeBatchSize * maxAcceptDepth * sizeof(int32_t), cudaMemcpyDeviceToHost, stream));
68	    CUDA_CHECK(cudaStreamSynchronize(stream));
69	
70	    for (int32_t batchIdx = 0; batchIdx < activeBatchSize; ++batchIdx)
71	    {
72	        int32_t const acceptLength = hostAcceptLengthsData[batchIdx];
73	        int32_t appended = 0;
74	        for (int32_t i = 0; i < acceptLength; i++)
75	        {
76	            int32_t const token = hostAcceptedTokenIdsData[batchIdx * maxAcceptDepth + i];
77	            context.tokenIds[batchIdx].push_back(token);
78	            context.currentGenerateLengths[batchIdx]++;
79	            ++appended;
80	            bool const shouldStop = context.shouldStopAfterAcceptedToken
81	                ? context.shouldStopAfterAcceptedToken(batchIdx, token)
82	                : token == tokenizer.getEosId();
83	            if (shouldStop)
84	            {
85	                break;
86	            }
87	        }
88	        // EOS / stop can end the slot mid-accept; write back the appended count so
89	        // collectSpecLogprobsFromHost skips verify rows past the end of the sequence.
90	        hostAcceptLengthsData[batchIdx] = appended;
91	    }
92	}
93	
94	void enqueueLogprobsD2H(
95	    Tensor const& inputLogits, int32_t rows, DecodingRuntimeContext& runtime, int32_t topK, cudaStream_t stream)
96	{
97	    check::check(runtime.logprobs.deviceLogprobsValues.reshape({rows, topK}), "Tensor reshape failed");
98	    check::check(runtime.logprobs.deviceLogprobsIndices.reshape({rows, topK}), "Tensor reshape failed");
99	    check::check(runtime.logprobs.hostLogprobsValues.reshape({rows, topK}), "Tensor reshape failed");
100	    check::check(runtime.logprobs.hostLogprobsIndices.reshape({rows, topK}), "Tensor reshape failed");
101	    extractTopKLogprobs(inputLogits, runtime.logprobs.deviceLogprobsValues, runtime.logprobs.deviceLogprobsIndices,
102	        topK, runtime.sampling.workspace, stream);
103	    if (runtime.deployment.base.reducedVocabSize > 0)
104	    {
105	        mapReducedVocabToFullVocab(
106	            runtime.logprobs.deviceLogprobsIndices, runtime.sampling.baseVocabMappingTable, stream);
107	    }
108	    CUDA_CHECK(cudaMemcpyAsync(runtime.logprobs.hostLogprobsValues.rawPointer(),
109	        runtime.logprobs.deviceLogprobsValues.rawPointer(), static_cast<size_t>(rows) * topK * sizeof(float),
110	        cudaMemcpyDeviceToHost, stream));
111	    CUDA_CHECK(cudaMemcpyAsync(runtime.logprobs.hostLogprobsIndices.rawPointer(),
112	        runtime.logprobs.deviceLogprobsIndices.rawPointer(), static_cast<size_t>(rows) * topK * sizeof(int32_t),
113	        cudaMemcpyDeviceToHost, stream));
114	}
115	
116	void collectLogprobsFromHost(
117	    DecodingRuntimeContext& runtime, DecodingInferenceContext& context, int32_t activeBatchSize, int32_t topK)
118	{
119	    float const* hostVals = runtime.logprobs.hostLogprobsValues.dataPointer<float>();
120	    int32_t const* hostIdx = runtime.logprobs.hostLogprobsIndices.dataPointer<int32_t>();
121	    for (int32_t i = 0; i < activeBatchSize; ++i)
122	    {
123	        if (context.finishedStates[i])
124	            continue;
125	        rt::LogprobsSlot& slot = context.stepLogprobs[i];
126	        int32_t const base = slot.numSteps * topK;
127	        check::check(static_cast<size_t>(base + topK) <= slot.data.size(), "logprobs slot overflow");
128	        for (int32_t k = 0; k < topK; ++k)
129	            slot.data[base + k] = {hostIdx[i * topK + k], hostVals[i * topK + k]};
130	        ++slot.numSteps;
131	    }
132	}
133	
134	void collectSpecLogprobsFromHost(DecodingRuntimeContext& runtime, DecodingInferenceContext& context,
135	    int32_t activeBatchSize, int32_t rowsPerBatch, int32_t const* hostAcceptLens, int32_t topK)
136	{
137	    float const* hostVals = runtime.logprobs.hostLogprobsValues.dataPointer<float>();
138	    int32_t const* hostIdx = runtime.logprobs.hostLogprobsIndices.dataPointer<int32_t>();
139	    for (int32_t i = 0; i < activeBatchSize; ++i)
140	    {
141	        if (context.finishedStates[i])
142	            continue;
143	        int32_t const acceptLen = hostAcceptLens[i];
144	        rt::LogprobsSlot& slot = context.stepLogprobs[i];
145	        for (int32_t j = 0; j < acceptLen; ++j)
146	        {
147	            int32_t const row = i * rowsPerBatch + j;
148	            int32_t const base = slot.numSteps * topK;
149	            check::check(static_cast<size_t>(base + topK) <= slot.data.size(), "logprobs slot overflow");
150	            for (int32_t k = 0; k < topK; ++k)
151	                slot.data[base + k] = {hostIdx[row * topK + k], hostVals[row * topK + k]};
152	            ++slot.numSteps;
153	        }
154	    }
155	}
