144	bool EagleDecoder::decodeStep(DecodingInferenceContext& context)
145	{
146	    if (context.generationRound == 0)
147	    {
148	        if (!runDraftModelPrefill(context))
149	        {
150	            LOG_ERROR("Failed to execute prefill step for draft model.");
151	            return false;
152	        }
153	    }
154	    else if (!runDraftModelAcceptToken(context))
155	    {
156	        LOG_ERROR("Failed to execute accept token step for draft model.");
157	        return false;
158	    }
159	
160	    if (!constructDraftProposal(context))
161	    {
162	        LOG_ERROR("Failed to construct draft proposal.");
163	        return false;
164	    }
165	
166	    if (!runBaseModelVerification(context))
167	    {
168	        LOG_ERROR("Failed to verify draft proposal with base model.");
169	        return false;
170	    }
171	    return true;
172	}
173	
174	bool EagleDecoder::runDraftModelPrefill(DecodingInferenceContext& context)
175	{
176	    assert(mDraftExecutor != nullptr);
177	    assert(mRuntime.deployment.specConfig.has_value());
178	    assert(mRuntime.deployment.draft.has_value());
179	    TIME_STAGE(metrics::StageNames::kSPEC_DECODE_DRAFT_PREFILL, context.stream);
180	    NVTX_SCOPED_RANGE(nvtx_draft_prefill,
181	        ("SPEC_DECODE_DRAFT_PREFILL[R" + std::to_string(context.generationRound) + ","
182	            + std::to_string(context.activeBatchSize) + "]")
183	            .c_str(),
184	        nvtx_colors::DARK_ORANGE);
185	
186	    int32_t const activeBatchSize = context.activeBatchSize;
187	    int32_t const draftHiddenSize = mRuntime.deployment.specConfig->draftHiddenSize;
188	    int32_t const draftVocabSize = mRuntime.deployment.draft->outputVocabSize;
189	    int32_t const inputIdsLength
190	        = *std::max_element(context.effectivePrefillLengths.begin(), context.effectivePrefillLengths.end());
191	
192	    check::check(mRuntime.base.pipelineIO.baseHiddenStates.getShape()[0] == activeBatchSize
193	            && mRuntime.base.pipelineIO.baseHiddenStates.getShape()[1] == inputIdsLength,
194	        "BaseHiddenStates shape [batch, seq_len, hidden_dim] shall match active prefill shape.");
195	
196	    check::check(mRuntime.preprocess.idsInput.reshape({activeBatchSize, inputIdsLength}), "Tensor reshape failed");
197	    check::check(
198	        mRuntime.base.pipelineIO.draftHiddenStatesIn.reshape({activeBatchSize, inputIdsLength, draftHiddenSize}),
199	        "Tensor reshape failed");
200	    check::check(
201	        mRuntime.base.pipelineIO.outputLogits.reshape({activeBatchSize, draftVocabSize}), "Tensor reshape failed");
202	    check::check(mRuntime.base.pipelineIO.draftHiddenStatesOut.reshape({activeBatchSize, draftHiddenSize}),
203	        "Tensor reshape failed");
204	    check::check(mRuntime.base.pipelineIO.hostContextLengths.reshape({activeBatchSize}), "Tensor reshape failed");
205	
206	    CUDA_CHECK(cudaMemsetAsync(mRuntime.base.pipelineIO.draftHiddenStatesIn.rawPointer(), 0,
207	        mRuntime.base.pipelineIO.draftHiddenStatesIn.getMemoryCapacity(), context.stream));
208	
209	    check::check(
210	        mRuntime.sampling.hostPackedTokenIds.reshape({activeBatchSize, inputIdsLength}), "Tensor reshape failed");
211	    int32_t* hostPackedTokenIdsData = mRuntime.sampling.hostPackedTokenIds.dataPointer<int32_t>();
212	    for (int32_t i = 0; i < activeBatchSize; ++i)
213	    {
214	        std::copy(
215	            context.tokenIds[i].begin() + 1, context.tokenIds[i].end(), hostPackedTokenIdsData + i * inputIdsLength);
216	    }
217	    CUDA_CHECK(cudaMemcpyAsync(mRuntime.preprocess.idsInput.rawPointer(), hostPackedTokenIdsData,
218	        activeBatchSize * inputIdsLength * sizeof(int32_t), cudaMemcpyHostToDevice, context.stream));
219	
220	    check::check(mRuntime.base.pipelineIO.inputsEmbeds.reshape({activeBatchSize, inputIdsLength, draftHiddenSize}),
221	        "Tensor reshape failed");
222	    if (context.visualEmbeddings.has_value())
223	    {
224	        Tensor const& imageEmbedsTensor = context.visualEmbeddings.value().get();
225	        kernel::embeddingLookupWithImageInsertion(mRuntime.preprocess.idsInput, mRuntime.preprocess.embedding.table,
226	            mRuntime.preprocess.embedding.scalesAsOptional(), imageEmbedsTensor, mRuntime.base.pipelineIO.inputsEmbeds,
227	            context.stream);
228	    }
229	    else
230	    {
231	        kernel::embeddingLookup(mRuntime.preprocess.idsInput, mRuntime.preprocess.embedding.table,
232	            mRuntime.preprocess.embedding.scalesAsOptional(), mRuntime.base.pipelineIO.inputsEmbeds, context.stream);
233	    }
234	    int32_t* ctxLenData = mRuntime.base.pipelineIO.hostContextLengths.dataPointer<int32_t>();
235	    for (int32_t i = 0; i < activeBatchSize; ++i)
236	    {
237	        ctxLenData[i] = context.effectivePrefillLengths[i];
238	    }
239	    CUDA_CHECK(cudaMemcpyAsync(mRuntime.base.pipelineIO.contextLengths.rawPointer(), ctxLenData,
240	        activeBatchSize * sizeof(int32_t), cudaMemcpyHostToDevice, context.stream));
241	
242	    check::check(mRuntime.base.pipelineIO.selectTokenIndices.reshape({activeBatchSize, 1}), "Tensor reshape failed");
243	    check::check(mRuntime.base.pipelineIO.hostSelectTokenIndices.reshape({activeBatchSize, 1}),
244	        "hostSelectTokenIndices reshape failed");
245	    int64_t* selectData = mRuntime.base.pipelineIO.hostSelectTokenIndices.dataPointer<int64_t>();
246	    for (int32_t i = 0; i < activeBatchSize; ++i)
247	    {
248	        selectData[i] = context.effectivePrefillLengths[i] - 1;
249	    }
250	    CUDA_CHECK(cudaMemcpyAsync(mRuntime.base.pipelineIO.selectTokenIndices.rawPointer(),
251	        mRuntime.base.pipelineIO.hostSelectTokenIndices.rawPointer(), activeBatchSize * sizeof(int64_t),
252	        cudaMemcpyHostToDevice, context.stream));
253	
254	    bool const draftKVAllEmpty = mDraftCacheManager.getKVCacheAllEmpty();
255	    auto const prefillDims = mRuntime.deployment.draft->prefillDims(activeBatchSize, inputIdsLength, draftKVAllEmpty);
256	    bool prefillSuccess = mDraftExecutor->prepare(kPrefillProfile, prefillDims, mDraftTensorMap, context.stream);
