342	        "Tensor reshape failed");
343	
344	    for (int32_t round = 0; round < mRuntime.deployment.specConfig->draftingStep - 1; round++)
345	    {
346	        if (round == 0)
347	        {
348	            kernel::assembleInitialIntermediateData(mRuntime.sampling.scores, mDraftTokenIntermediateParents,
349	                mDraftTokenIntermediateScores, draftTopK, context.stream);
