354	            check::check(mRuntime.sampling.scores.reshape({activeBatchSize, draftTopK}), "Tensor reshape failed");
355	            selectAllTopK(mDraftTokenScoresTable, std::ref(mRuntime.sampling.scores), mRuntime.sampling.indices,
356	                draftTopK, mRuntime.sampling.workspace, context.stream);
357	            kernel::assembleDraftTreeInput(mDraftTokenIdsTable, mRuntime.base.pipelineIO.draftHiddenStatesOut,
358	                mRuntime.sampling.indices, mRuntime.preprocess.idsInput, mRuntime.base.pipelineIO.draftHiddenStatesIn,
359	                mDraftProposalSize, mDraftAttentionMask, draftTopK, round, context.stream);
360	            kernel::assembleIntermediateData(mRuntime.sampling.scores, mRuntime.sampling.indices,
361	                mDraftTokenIntermediateScores, mDraftTokenIntermediateParents, draftTopK, round, context.stream);
362	        }
363	
364	        check::check(mRuntime.base.pipelineIO.outputLogits.reshape({activeBatchSize, draftTopK, draftVocabSize}),
365	            "Tensor reshape failed");
366	        check::check(
367	            mRuntime.base.pipelineIO.draftHiddenStatesOut.reshape({activeBatchSize, draftTopK, draftHiddenSize}),
368	            "Tensor reshape failed");
