438	bool EagleDecoder::runBaseModelVerification(DecodingInferenceContext& context)
439	{
440	    assert(mDraftExecutor != nullptr);
441	    assert(mRuntime.deployment.specConfig.has_value());
442	    TIME_STAGE(metrics::StageNames::kSPEC_DECODE_BASE_VERIFICATION, context.stream);
443	    NVTX_SCOPED_RANGE(nvtx_verify,
444	        ("SPEC_DECODE_VERIFY[R" + std::to_string(context.generationRound) + ","
445	            + std::to_string(context.activeBatchSize) + "]")
446	            .c_str(),
447	        nvtx_colors::MAGENTA);
448	
449	    int32_t const activeBatchSize = context.activeBatchSize;
450	    int32_t const baseOutputHiddenDim = mRuntime.deployment.specConfig->baseOutputHiddenDim;
451	
452	    check::check(mRuntime.preprocess.idsInput.getShape()[0] == activeBatchSize
453	            && mRuntime.preprocess.idsInput.getShape()[1] == mRuntime.deployment.specConfig->verifySize,
454	        "IdsInput shall have shape [batch_size, verify_size]");
455	    check::check(mDraftAttentionMask.getShape()[0] == activeBatchSize
456	            && mDraftAttentionMask.getShape()[1] == mRuntime.deployment.specConfig->verifySize
457	            && mDraftAttentionMask.getShape()[2] == mRuntime.deployment.specConfig->verifySize,
458	        "Draft attention mask shall have shape [batch_size, verify_size, verify_size]");
459	
460	    check::check(mRuntime.base.pipelineIO.inputsEmbeds.reshape({activeBatchSize,
461	                     mRuntime.deployment.specConfig->verifySize, mRuntime.deployment.base.hiddenSize}),
462	        "Tensor reshape failed");
463	    kernel::embeddingLookup(mRuntime.preprocess.idsInput, mRuntime.preprocess.embedding.table,
464	        mRuntime.preprocess.embedding.scalesAsOptional(), mRuntime.base.pipelineIO.inputsEmbeds, context.stream);
465	    int32_t const selectTokenSize = activeBatchSize * mRuntime.deployment.specConfig->verifySize;
466	    check::check(
467	        mRuntime.base.pipelineIO.outputLogits.reshape({selectTokenSize, mRuntime.deployment.base.outputVocabSize}),
468	        "Tensor reshape failed");
469	    check::check(mRuntime.base.pipelineIO.baseHiddenStates.reshape({selectTokenSize, baseOutputHiddenDim}),
470	        "Tensor reshape failed");
471	
472	    {
473	        int32_t const verifySize = mRuntime.deployment.specConfig->verifySize;
474	        Tensor const& baseKVCacheLengths = mRuntime.base.cacheManager.getKVCacheLengths();
475	        check::check(mRuntime.base.pipelineIO.selectTokenIndices.reshape({activeBatchSize, verifySize}),
476	            "Tensor reshape failed");
477	        check::check(mRuntime.base.pipelineIO.contextLengths.reshape({activeBatchSize}), "Tensor reshape failed");
478	        check::check(mRuntime.base.pipelineIO.specDecodePositionIds.reshape({activeBatchSize, verifySize}),
479	            "Tensor reshape failed");
480	        kernel::prepareEagleBaseTreeDecodingInputs(mDraftAttentionMask, baseKVCacheLengths,
481	            mRuntime.base.pipelineIO.packedAttentionMask, mRuntime.base.pipelineIO.specDecodePositionIds,
482	            mRuntime.base.pipelineIO.selectTokenIndices, mRuntime.base.pipelineIO.contextLengths, context.stream);
483	    }
484	
485	    if (mRuntime.preprocess.deepstack)
486	    {
487	        mRuntime.preprocess.deepstack->useZeroTarget(mRuntime.base.tensorMap);
488	    }
489	
490	    // Eagle: no prepareBaseVerificationState needed
491	
492	    auto const verifyDims
493	        = mRuntime.deployment.base.specVerifyDims(activeBatchSize, mRuntime.deployment.specConfig->verifySize);
494	    bool verifySuccess
495	        = mRuntime.base.executor.prepare(kDecodeProfile, verifyDims, mRuntime.base.tensorMap, context.stream);
496	    if (verifySuccess)
497	    {
498	        verifySuccess = mRuntime.base.executor.execute(context.stream);
499	    }
500	    if (!verifySuccess)
501	    {
502	        LOG_ERROR("Failed to execute base verification step for base model.");
503	        return false;
504	    }
505	
506	    int32_t const maxAcceptDepth = mRuntime.deployment.specConfig->draftingStep + 1;
507	    check::check(mAcceptedTokenIds.reshape({activeBatchSize, maxAcceptDepth}), "Tensor reshape failed");
508	    check::check(mAcceptedTokenIndices.reshape({activeBatchSize, maxAcceptDepth}), "Tensor reshape failed");
509	    check::check(mAcceptLength.reshape({activeBatchSize}), "Tensor reshape failed");
510	
511	    OptionalInputTensor vocabMappingTable = (mRuntime.deployment.base.reducedVocabSize > 0)
512	        ? std::optional{std::ref(mRuntime.sampling.baseVocabMappingTable)}
513	        : std::nullopt;
514	    kernel::eagleAccept(mRuntime.base.pipelineIO.outputLogits, mRuntime.preprocess.idsInput, mDraftAttentionMask,
515	        mAcceptedTokenIds, mAcceptedTokenIndices, mAcceptLength, vocabMappingTable,
516	        mRuntime.sampling.workspace.rawPointer(), mRuntime.sampling.workspace.getMemoryCapacity(), context.stream);
517	
518	    auto& cacheMgrBase = mRuntime.base.cacheManager;
519	    Tensor const& kvCacheLengths = cacheMgrBase.getKVCacheLengths();
520	    auto& kvMgrBase = cacheMgrBase.getKVCacheManager();
521	    auto const kvHeadDimGroups = cacheMgrBase.getKVHeadDimGroups();
522	    auto const kvCacheType = kvMgrBase.getConfig().kvCacheType;
523	
524	    check::check(mRuntime.base.pipelineIO.baseHiddenStates.reshape(
525	                     {activeBatchSize, mRuntime.deployment.specConfig->verifySize, baseOutputHiddenDim}),
526	        "Tensor reshape failed");
527	
528	    for (auto const& group : kvHeadDimGroups)
529	    {
530	        kernel::eagleBaseCommitKVCache(mAcceptedTokenIndices, mAcceptLength, kvCacheLengths, group.deviceLayerInfos,
531	            group.numLayers, group.headDim, group.maxKVHeads, activeBatchSize, maxAcceptDepth, kvCacheType,
532	            context.stream);
533	    }
534	    kernel::eagleBaseAssembleHiddenState(
535	        mAcceptedTokenIndices, mAcceptLength, mRuntime.base.pipelineIO.baseHiddenStates, context.stream);
536	    mRuntime.base.cacheManager.commitSequenceLength(mAcceptLength, context.stream);
537	    // Eagle: no commitAcceptedBaseState needed
538	
539	    check::check(
540	        mRuntime.base.pipelineIO.baseHiddenStates.reshape({activeBatchSize, maxAcceptDepth, baseOutputHiddenDim}),
541	        "Tensor reshape failed");
542	
543	    // Enqueue logprobs device work + D2H before appendAcceptedTokens so everything rides
544	    // that call's single round synchronization.
545	    if (context.numLogprobs > 0)
546	    {
547	        int32_t const verifyTreeSize = mRuntime.deployment.specConfig->verifySize;
548	        int32_t const vocabSize = mRuntime.deployment.base.outputVocabSize;
549	        int32_t const gatheredRows = activeBatchSize * maxAcceptDepth;
550	        check::check(mRuntime.logprobs.gatheredLogits.reshape({gatheredRows, vocabSize}), "Tensor reshape failed");
551	        gatherSpecVerifyAcceptedLogitRows(mRuntime.base.pipelineIO.outputLogits, mAcceptedTokenIndices,
552	            mRuntime.logprobs.gatheredLogits, activeBatchSize, verifyTreeSize, maxAcceptDepth, vocabSize,
553	            context.stream);
554	        decoder_utils::enqueueLogprobsD2H(
555	            mRuntime.logprobs.gatheredLogits, gatheredRows, mRuntime, context.numLogprobs, context.stream);
556	    }
557	
558	    decoder_utils::appendAcceptedTokens(context, mHostAcceptLengths, mHostAcceptedTokenIds, mAcceptLength,
559	        mAcceptedTokenIds, maxAcceptDepth, mRuntime.tokenizer, context.stream);
560	
561	    if (context.numLogprobs > 0)
562	    {
563	        decoder_utils::collectSpecLogprobsFromHost(mRuntime, context, activeBatchSize, maxAcceptDepth,
564	            mHostAcceptLengths.dataPointer<int32_t>(), context.numLogprobs);
565	    }
566	
567	    return true;
568	}
