377	                mRuntime.base.pipelineIO.specDecodePositionIds.reshape({activeBatchSize, paddedDraftProposalSize}),
378	                "Tensor reshape failed");
379	            kernel::prepareEagleDraftProposalInputs(mDraftAttentionMask, mDraftProposalSize, draftKVCacheLengths,
380	                mRuntime.base.pipelineIO.packedAttentionMask, mRuntime.base.pipelineIO.specDecodePositionIds,
381	                mRuntime.base.pipelineIO.selectTokenIndices, mRuntime.base.pipelineIO.contextLengths, context.stream);
382	        }
383	
384	        auto const proposalDims
385	            = mRuntime.deployment.draft->proposalDims(activeBatchSize, paddedDraftProposalSize, draftTopK);
386	        check::check(mDraftExecutor->prepare(kDecodeProfile, proposalDims, mDraftTensorMap, context.stream),
387	            "Failed to prepare draft model for draft proposal step.");
388	        check::check(mDraftExecutor->execute(context.stream), "Failed to execute draft model for draft proposal step.");
389	
390	        check::check(mRuntime.base.pipelineIO.outputLogits.reshape({activeBatchSize * draftTopK, draftVocabSize}),
391	            "Tensor reshape failed");
392	        check::check(
393	            mRuntime.base.pipelineIO.draftHiddenStatesOut.reshape({activeBatchSize * draftTopK, draftHiddenSize}),
394	            "Tensor reshape failed");
395	        check::check(
396	            mRuntime.sampling.indices.reshape({activeBatchSize * draftTopK, draftTopK}), "Tensor reshape failed");
397	        check::check(
398	            mRuntime.sampling.scores.reshape({activeBatchSize * draftTopK, draftTopK}), "Tensor reshape failed");
399	        selectAllTopK(mRuntime.base.pipelineIO.outputLogits, std::ref(mRuntime.sampling.scores),
400	            mRuntime.sampling.indices, draftTopK, mRuntime.sampling.workspace, context.stream);
401	
402	        check::check(
403	            mRuntime.sampling.indices.reshape({activeBatchSize, draftTopK * draftTopK}), "Tensor reshape failed");
404	        check::check(
405	            mRuntime.sampling.scores.reshape({activeBatchSize, draftTopK * draftTopK}), "Tensor reshape failed");
406	        kernel::computeCuScoresAndTranslateToken(mRuntime.sampling.indices, mRuntime.sampling.scores,
407	            mDraftTokenIntermediateScores, mDraftVocabMappingTable, mDraftTokenIdsTable, mDraftTokenScoresTable,
408	            draftTopK, context.stream);
409	        kernel::updateDraftTreeFullTables(mDraftTokenIdsTable, mDraftTokenScoresTable, mDraftTokenIntermediateParents,
410	            mDraftTokenIdsFullTable, mDraftTokenScoreFullTable, mDraftTokenPredecessorFullTable, draftTopK, round,
411	            context.stream);
412	    }
413	
414	    check::check(mRuntime.sampling.indices.reshape({activeBatchSize, mRuntime.deployment.specConfig->verifySize}),
415	        "Tensor reshape failed");
416	    selectAllTopK(mDraftTokenScoreFullTable, std::nullopt, mRuntime.sampling.indices,
417	        mRuntime.deployment.specConfig->verifySize, mRuntime.sampling.workspace, context.stream);
418	
419	    check::check(mRuntime.preprocess.idsInput.reshape({activeBatchSize, mRuntime.deployment.specConfig->verifySize}),
420	        "Tensor reshape failed");
421	    check::check(mDraftAttentionMask.reshape({activeBatchSize, mRuntime.deployment.specConfig->verifySize,
422	                     mRuntime.deployment.specConfig->verifySize}),
423	        "Tensor reshape failed");
424	    check::check(mRuntime.base.pipelineIO.packedAttentionMask.reshape(
425	                     {activeBatchSize, mRuntime.deployment.specConfig->verifySize,
426	                         static_cast<int64_t>(divUp(mRuntime.deployment.specConfig->verifySize, 32))}),
427	        "Tensor reshape failed");
428	    kernel::constructVerificationDraftTree(mDraftTokenIdsFullTable, mDraftTokenPredecessorFullTable,
429	        mRuntime.sampling.indices, mRuntime.preprocess.idsInput, mDraftAttentionMask, context.stream);
430	
431	    return true;
432	}
