261	bool DFlashDecoder::runDraftForward(DecodingInferenceContext& context)
262	{
263	    TIME_STAGE(metrics::StageNames::kSPEC_DECODE_DRAFT_PROPOSAL, context.stream);
264	    NVTX_SCOPED_RANGE(nvtx_dflash_draft, "DFlashDecoder::runDraftForward", nvtx_colors::DARK_ORANGE);
265	
266	    if (!mDraftExecutor)
267	    {
268	        LOG_ERROR("DFlashDecoder: draft engine not loaded.");
269	        return false;
270	    }
271	
272	    int32_t const activeBatchSize = context.activeBatchSize;
273	    int32_t const BS = mBlockSize;
274	
275	    // Step 1: Prepare draft input token IDs: [last_accepted_token, mask_id, ..., mask_id].
276	    check::check(mRuntime.preprocess.idsInput.reshape({activeBatchSize, BS}), "Tensor reshape failed");
277	    check::check(mHostDraftInputIds.reshape({activeBatchSize, BS}), "Tensor reshape failed");
278	    check::check(mHostLastAcceptedTokens.reshape({activeBatchSize}), "Tensor reshape failed");
279	    check::check(mLastAcceptedTokens.reshape({activeBatchSize}), "Tensor reshape failed");
280	    int32_t* hostDraftInputIds = mHostDraftInputIds.dataPointer<int32_t>();
281	    int32_t* hostLastAccepted = mHostLastAcceptedTokens.dataPointer<int32_t>();
282	    for (int32_t b = 0; b < activeBatchSize; ++b)
283	    {
284	        hostLastAccepted[b] = context.tokenIds[b].back();
285	        hostDraftInputIds[b * BS] = hostLastAccepted[b];
286	        for (int32_t j = 1; j < BS; ++j)
287	        {
288	            hostDraftInputIds[b * BS + j] = mMaskTokenId;
289	        }
290	    }
291	    CUDA_CHECK(cudaMemcpyAsync(mRuntime.preprocess.idsInput.rawPointer(), mHostDraftInputIds.rawPointer(),
292	        activeBatchSize * BS * sizeof(int32_t), cudaMemcpyHostToDevice, context.stream));
293	    CUDA_CHECK(cudaMemcpyAsync(mLastAcceptedTokens.rawPointer(), mHostLastAcceptedTokens.rawPointer(),
294	        activeBatchSize * sizeof(int32_t), cudaMemcpyHostToDevice, context.stream));
295	
296	    // Step 2: Embed the draft inputs.
297	    check::check(mDraftInputsEmbeds.reshape({activeBatchSize, BS, mDraftHiddenSize}), "Tensor reshape failed");
298	    kernel::embeddingLookup(mRuntime.preprocess.idsInput, mRuntime.preprocess.embedding.table,
299	        mRuntime.preprocess.embedding.scalesAsOptional(), mDraftInputsEmbeds, context.stream);
300	
301	    // Step 3: Prepare target-hidden delta from base hidden states.
302	    // Round 0 uses prefill hidden states; later rounds use accepted base hidden states.
303	    // The draft KV update plugin consumes per-batch delta_lengths to skip padded rows.
304	    int64_t maxDeltaLen;
305	    int64_t sourceSeqLen;
306	    check::check(mHostDeltaLens.reshape({activeBatchSize}), "Tensor reshape failed");
307	    int32_t* hostDeltaLens = mHostDeltaLens.dataPointer<int32_t>();
308	    if (context.generationRound == 0)
309	    {
310	        sourceSeqLen = mRuntime.base.pipelineIO.baseHiddenStates.getShape()[1];
311	        maxDeltaLen = 0;
312	        for (int32_t b = 0; b < activeBatchSize; ++b)
313	        {
314	            int32_t const prefillLen = context.effectivePrefillLengths[b];
315	            hostDeltaLens[b] = prefillLen;
316	            maxDeltaLen = std::max(maxDeltaLen, static_cast<int64_t>(prefillLen));
317	        }
318	    }
319	    else
320	    {
321	        sourceSeqLen = mRuntime.base.pipelineIO.baseHiddenStates.getShape()[1];
322	        int32_t const* hostAccLens = mHostAcceptLengths.dataPointer<int32_t>();
323	        maxDeltaLen = 0;
324	        for (int32_t b = 0; b < activeBatchSize; ++b)
325	        {
326	            hostDeltaLens[b] = hostAccLens[b];
327	            maxDeltaLen = std::max(maxDeltaLen, static_cast<int64_t>(hostAccLens[b]));
328	        }
329	    }
330	
331	    check::check(mDraftDeltaLens.reshape({activeBatchSize}), "Tensor reshape failed");
332	    CUDA_CHECK(cudaMemcpyAsync(mDraftDeltaLens.rawPointer(), mHostDeltaLens.rawPointer(),
333	        activeBatchSize * sizeof(int32_t), cudaMemcpyHostToDevice, context.stream));
334	
335	    auto const compactTargetHidden = [&](Tensor& targetHidden) {
336	        check::check(
337	            targetHidden.reshape({activeBatchSize, maxDeltaLen, mBaseOutputHiddenDim}), "Tensor reshape failed");
338	        size_t const elementBytes = utils::getTypeSize(targetHidden.getDataType());
339	        size_t const rowBytes = static_cast<size_t>(mBaseOutputHiddenDim) * elementBytes;
340	        size_t const dstPitch = static_cast<size_t>(maxDeltaLen) * rowBytes;
341	        size_t const srcPitch = static_cast<size_t>(sourceSeqLen) * rowBytes;
342	        size_t const widthBytes = static_cast<size_t>(maxDeltaLen) * rowBytes;
343	        CUDA_CHECK(cudaMemcpy2DAsync(targetHidden.rawPointer(), dstPitch,
344	            mRuntime.base.pipelineIO.baseHiddenStates.rawPointer(), srcPitch, widthBytes, activeBatchSize,
345	            cudaMemcpyDeviceToDevice, context.stream));
346	        mDraftTensorMap.set(binding_names::kDFlashTargetHiddenConcat, targetHidden);
347	    };
348	
349	    // TensorRT reads dflash_target_hidden_concat as a compact [B, selectLen, H]
350	    // tensor. Bind baseHiddenStates directly only when its batch stride already
351	    // matches selectLen; otherwise compact into a scratch buffer first.
352	    if (context.generationRound == 0 && sourceSeqLen == maxDeltaLen)
353	    {
354	        // This intentionally narrows baseHiddenStates to the compact draft binding shape. The base runner reshapes
355	        // and rebinds it before the next base-engine enqueue.
356	        check::check(
357	            mRuntime.base.pipelineIO.baseHiddenStates.reshape({activeBatchSize, maxDeltaLen, mBaseOutputHiddenDim}),
358	            "Tensor reshape failed");
359	        mDraftTensorMap.set(binding_names::kDFlashTargetHiddenConcat, mRuntime.base.pipelineIO.baseHiddenStates);
360	    }
361	    else
362	    {
363	        check::check(context.generationRound == 0 || maxDeltaLen <= mBlockSize,
364	            "DFlash decode target-hidden delta exceeds block-size scratch.");
365	        if (maxDeltaLen <= mBlockSize)
366	        {
367	            compactTargetHidden(mDraftTargetHidden);
368	        }
369	        else
370	        {
371	            // This is only for an uncommon round-0 layout where baseHiddenStates
372	            // is wider than the active max prefill length. Keep it lazy so the
373	            // normal DFlash path does not pay a max-input/max-KV allocation.
374	            int32_t const reserveBatchSize = mRuntime.maxRuntimeBatchSize;
375	            int64_t const requiredBytes = static_cast<int64_t>(reserveBatchSize) * maxDeltaLen * mBaseOutputHiddenDim
376	                * static_cast<int64_t>(utils::getTypeSize(nvinfer1::DataType::kHALF));
377	            if (mDraftPrefillTargetHidden.getMemoryCapacity() < requiredBytes)
378	            {
379	                mDraftPrefillTargetHidden = Tensor{};
380	                mDraftPrefillTargetHidden = Tensor({reserveBatchSize, maxDeltaLen, mBaseOutputHiddenDim},
381	                    DeviceType::kGPU, nvinfer1::DataType::kHALF, "DFlashDraft::prefillTargetHiddenScratch");
382	            }
383	            compactTargetHidden(mDraftPrefillTargetHidden);
384	        }
385	    }
386	
387	    // Step 4: Prepare proposal attention inputs.
388	    int32_t const pmLen = divUp(BS, 32);
389	    check::check(mDraftPackedAttentionMask.reshape({activeBatchSize, BS, pmLen}), "Tensor reshape failed");
390	    check::check(mDraftAttentionPosId.reshape({activeBatchSize, BS}), "Tensor reshape failed");
391	    check::check(mDraftContextLengths.reshape({activeBatchSize}), "Tensor reshape failed");
392	    Tensor const& draftCacheLengths = mDraftCacheManager.getKVCacheLengths();
393	    kernel::launchDFlashPrepareProposalInputs(draftCacheLengths.dataPointer<int32_t>(),
394	        mDraftDeltaLens.dataPointer<int32_t>(), BS, mDraftPackedAttentionMask.dataPointer<int32_t>(),
395	        mDraftAttentionPosId.dataPointer<int32_t>(), mDraftContextLengths.dataPointer<int32_t>(), activeBatchSize,
396	        context.stream);
397	
398	    // Step 5: Execute the DFlash draft engine.
399	    check::check(mDraftOutputLogits.reshape({activeBatchSize, BS, mDraftVocabSize}), "Tensor reshape failed");
400	    int32_t const draftKVCapacity = mRuntime.deployment.draft->maxKVCacheCapacity;
401	    InferenceDims const draftDims{
402	        /*.batch=*/activeBatchSize,
403	        /*.seqLen=*/BS,
404	        /*.kvLen=*/draftKVCapacity,
405	        /*.selectLen=*/static_cast<int64_t>(maxDeltaLen),
406	        /*.attnMaskSeqLen=*/BS,
407	        /*.ropeBatch=*/1,
408	        /*.packedMaskLen=*/static_cast<int64_t>(pmLen),
409	        /*.startIndexLen=*/activeBatchSize,
410	        /*.specVerifyPhaseLen=*/0,
411	    };
412	
413	    bool draftSuccess = mDraftExecutor->prepare(
414	        dflashDraftProfileForRound(context.generationRound), draftDims, mDraftTensorMap, context.stream);
415	    if (draftSuccess)
416	    {
417	        draftSuccess = mDraftExecutor->execute(context.stream);
418	    }
419	    if (!draftSuccess)
420	    {
421	        LOG_ERROR("DFlashDecoder: draft engine execution failed.");
422	        return false;
423	    }
424	
425	    // Step 6: Commit per-batch delta lengths to the draft cache manager.
426	    if (context.generationRound == 0)
427	    {
428	        check::check(mDraftDeltaLenCommit.reshape({activeBatchSize}), "Tensor reshape failed");
429	        CUDA_CHECK(cudaMemcpyAsync(mDraftDeltaLenCommit.rawPointer(), mHostDeltaLens.rawPointer(),
430	            activeBatchSize * sizeof(int32_t), cudaMemcpyHostToDevice, context.stream));
431	        mDraftCacheManager.commitSequenceLength(mDraftDeltaLenCommit, context.stream);
432	    }
433	    else
434	    {
435	        check::check(mAcceptLength.reshape({activeBatchSize}), "Tensor reshape failed");
436	        mDraftCacheManager.commitSequenceLength(mAcceptLength, context.stream);
437	    }
438	
439	    return true;
440	}
441	
442	bool DFlashDecoder::prepareDFlashVerifyInputs(DecodingInferenceContext& context)
443	{
444	    NVTX_SCOPED_RANGE(
445	        nvtx_dflash_prepare_verify, "DFlashDecoder::prepareDFlashVerifyInputs", nvtx_colors::LIGHT_ORANGE);
446	
447	    int32_t const activeBatchSize = context.activeBatchSize;
448	    int32_t const verifySize = mUseDDTree ? mVerifySize : mBlockSize;
449	    check::check(mVerifyTokenIds.reshape({activeBatchSize, verifySize}), "Tensor reshape failed");
450	    check::check(mVerifyTreeMask.reshape({activeBatchSize, verifySize, verifySize}), "Tensor reshape failed");
451	
452	    if (!mUseDDTree)
453	    {
454	        // Linear DFlash uses candidateTopK == 1: select one draft token per block
455	        // position, then build a causal verify tree in the shared verify buffers.
456	        check::check(
457	            mDraftOutputLogits.reshape({activeBatchSize * mBlockSize, mDraftVocabSize}), "Tensor reshape failed");
458	        check::check(mDraftTokenIds.reshape({activeBatchSize * mBlockSize, 1}), "Tensor reshape failed");
459	        selectAllTopK(mDraftOutputLogits, std::nullopt, mDraftTokenIds, 1, mRuntime.sampling.workspace, context.stream);
460	        check::check(mDraftTokenIds.reshape({activeBatchSize, mBlockSize}), "Tensor reshape failed");
461	
462	        // Remap reduced-vocab draft IDs to full-vocab IDs before base verify.
463	        if (mHasDraftVocabMap)
464	        {
