466	            mapReducedVocabToFullVocab(mDraftTokenIds, mDraftVocabMappingTable, context.stream);
467	            check::check(mDraftTokenIds.reshape({activeBatchSize, mBlockSize}), "Tensor reshape failed");
468	        }
