470	        kernel::launchDFlashBuildLinearVerifyInputs(mLastAcceptedTokens.dataPointer<int32_t>(),
471	            mDraftTokenIds.dataPointer<int32_t>(), mVerifyTokenIds.dataPointer<int32_t>(),
472	            mVerifyTreeMask.dataPointer<int8_t>(), activeBatchSize, mBlockSize, context.stream);
473	        prepareLinearBaseVerificationMetadata(activeBatchSize, verifySize, context.stream);
