64	DecodingStrategy& DecoderRegistry::select(LLMGenerationRequest const& request) const noexcept
65	{
66	    if (!mSpeculativeDecoder || request.disableSpecDecode)
67	    {
68	        return *mDefaultDecoder;
69	    }
70	
71	    return *mSpeculativeDecoder;
72	}
