79	bool DecoderRegistry::captureCudaGraphs(cudaStream_t stream) const
80	{
81	    bool const skipDefaultCapture = mSpeculativeDecoder && mSpeculativeDecoder->kind() == DecodingStrategyKind::kDFlash;
82	    if (skipDefaultCapture)
83	    {
84	        LOG_INFO("Skipping vanilla CUDA graph capture for DFlash speculative runtime.");
85	    }
86	    bool const defaultCaptureStatus
87	        = (!skipDefaultCapture && mDefaultDecoder) ? mDefaultDecoder->captureCudaGraphs(stream) : true;
88	    bool const speculativeCaptureStatus = mSpeculativeDecoder ? mSpeculativeDecoder->captureCudaGraphs(stream) : true;
89	    bool const captureStatus = defaultCaptureStatus && speculativeCaptureStatus;
90	    if (captureStatus)
91	    {
92	        LOG_INFO("Successfully captured decoding CUDA graphs for active decoding strategies.");
93	    }
94	    else
95	    {
96	        LOG_WARNING(
97	            "Failed to capture decoding CUDA graphs for some stages. The inference can proceed without "
98	            "CUDA graph capture, but at cost of performance degradation.");
99	    }
100	    return captureStatus;
101	}
